"""Offline positive and negative controls for #9908's PR introduction gate."""
from __future__ import annotations

import importlib.util
import io
import shutil
import subprocess
import tempfile
import unittest
from contextlib import redirect_stdout
from pathlib import Path, PurePosixPath

import yaml

SCRIPT = Path(__file__).with_name("check-service-application-readiness.py")
spec = importlib.util.spec_from_file_location("service_readiness", SCRIPT)
assert spec and spec.loader
gate = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gate)
SOURCE_ROOT = SCRIPT.parents[2]


def git(root: Path, *args: str) -> str:
    return subprocess.check_output(["git", "-C", str(root), *args], text=True, env=gate.git_env()).strip()


def write_yaml(path: Path, value: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(yaml.safe_dump(value, sort_keys=False))


class ReadinessTests(unittest.TestCase):
    def setUp(self) -> None:
        self.tmp = tempfile.TemporaryDirectory(prefix="service-readiness-test-")
        self.root = Path(self.tmp.name)
        self.component = PurePosixPath("openbank-infra/gitops/components/demo")
        self.apps = self.root / "openbank-infra/gitops/apps"
        self.apps.mkdir(parents=True)
        self.comp = self.root / self.component
        self.comp.mkdir(parents=True)
        scripts = self.root / "openbank-infra/scripts"
        scripts.mkdir(parents=True)
        for name in ("check-threat-models.py", "check-cnpg-backup-declared.py"):
            shutil.copyfile(SOURCE_ROOT / "openbank-infra/scripts" / name, scripts / name)
        for name in ("openbank-one-service", "openbank-two-service"):
            module = self.root / name
            module.mkdir()
            (module / "build.gradle.kts").write_text(
                'plugins { id("openbank.quarkus-service") }\n'
                'dependencies { implementation(project(":openbank-libs-runtime")) }\n'
            )
            model = self.root / "docs/threat-models" / f"{name}.md"
            model.parent.mkdir(parents=True, exist_ok=True)
            model.write_text("# STRIDE threat model\n" + "Trust boundary and mitigation. " * 25)
        self.app = {
            "apiVersion": "argoproj.io/v1alpha1", "kind": "Application",
            "metadata": {"name": "demo", "namespace": "argocd"},
            "spec": {"source": {"path": str(self.component)}, "destination": {"namespace": "demo"},
                     "syncPolicy": {}},
        }
        write_yaml(self.apps / "demo.yaml", self.app)
        self.workload = {
            "apiVersion": "apps/v1", "kind": "Deployment",
            "metadata": {"name": "one", "namespace": "demo"},
            "spec": {"template": {"metadata": {"annotations": {gate.CHECKSUM: "abc"}},
                                  "spec": {"volumes": [{"name": "opa-bundle", "configMap": {"name": "one-opa-bundle"}}],
                                           "containers": [
                                      {"name": "app", "image": "registry.example/openbank-one-service:example"},
                                      {"name": "opa", "image": "docker.io/openpolicyagent/opa:1.21.1",
                                       "volumeMounts": [{"name": "opa-bundle", "mountPath": "/bundle"}]},
                                  ]}}},
        }
        write_yaml(self.comp / "one.yaml", self.workload)
        write_yaml(self.comp / "one-opa-bundle.yaml", {
            "apiVersion": "v1", "kind": "ConfigMap", "metadata": {"name": "one-opa-bundle", "namespace": "demo", "annotations": {gate.CHECKSUM: "abc"}},
            "data": {"policy": "abc"},
        })
        bundle = self.comp / "one-opa-bundle.yaml"
        bundle.write_text("# GENERATED by gen-one-opa-bundle.sh — do not hand-edit.\n" + bundle.read_text())
        generator = self.comp / "gen-one-opa-bundle.sh"
        generator.write_text(
            '#!/bin/sh\nset -eu\n'
            'root="$(git rev-parse --show-toplevel)"\n'
            'cat > "$root/openbank-infra/gitops/components/demo/one-opa-bundle.yaml" <<EOF\n'
            '# GENERATED by gen-one-opa-bundle.sh — do not hand-edit.\n'
            'apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: one-opa-bundle\n  namespace: demo\n'
            '  annotations:\n    openbank.tech/policy-checksum: abc\n'
            'data:\n  policy: abc\nEOF\n'
            'sed -i.bak \'s/policy-checksum: .*/policy-checksum: abc/\' '
            '"$root/openbank-infra/gitops/components/demo/one.yaml"\n'
            'rm -f "$root/openbank-infra/gitops/components/demo/one.yaml.bak"\n'
        )
        generator.chmod(0o755)
        self.backup = {
            "apiVersion": "postgresql.cnpg.io/v1", "kind": "Cluster",
            "metadata": {"name": "demo-db", "namespace": "demo"},
            "spec": {"backup": {"barmanObjectStore": {"destinationPath": "s3://test-only"}}},
        }
        write_yaml(self.comp / "postgres.yaml", self.backup)
        self.schedule = {
            "apiVersion": "postgresql.cnpg.io/v1", "kind": "ScheduledBackup",
            "metadata": {"name": "demo-daily", "namespace": "demo"},
            "spec": {"cluster": {"name": "demo-db"}, "immediate": True},
        }
        write_yaml(self.comp / "backup.yaml", self.schedule)
        git(self.root, "init", "-q")
        git(self.root, "config", "user.name", "readiness fixture")
        git(self.root, "config", "user.email", "fixture@example.invalid")
        git(self.root, "config", "commit.gpgsign", "false")  # disposable fixture repository only
        git(self.root, "add", "--", "openbank-infra", "openbank-one-service", "openbank-two-service", "docs")
        git(self.root, "commit", "-qm", "staged base")
        self.base = git(self.root, "rev-parse", "HEAD")

    def tearDown(self) -> None:
        self.tmp.cleanup()

    def commit(self, message: str) -> None:
        git(self.root, "add", "--", "openbank-infra", "docs")
        git(self.root, "commit", "-qm", message)

    def test_staged_then_promoted_and_existing_auto_workload(self) -> None:
        self.assertEqual(gate.check_component(self.root, self.component, self.app)[0], 0)
        self.assertEqual(gate.verify_generated(self.root, {self.component: gate.check_component(self.root, self.component)[1]}), 0)
        (self.comp / "other.yaml").write_text("apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: added\n")
        self.commit("staged component change")
        self.assertEqual(gate.selected_applications(self.root, self.base), [])
        self.app["spec"]["syncPolicy"] = {"automated": {"prune": True}}
        write_yaml(self.apps / "demo.yaml", self.app)
        self.commit("promote")
        self.assertEqual(len(gate.selected_applications(self.root, self.base)), 1)
        promoted = git(self.root, "rev-parse", "HEAD")
        write_yaml(self.comp / "two.yaml", {
            "apiVersion": "apps/v1", "kind": "Deployment",
            "metadata": {"name": "two"},
            "spec": {"template": {"spec": {"containers": [
                {"name": "app", "image": "registry.example/openbank-two-service:example"}]}}},
        })
        self.commit("add workload to automated app")
        self.assertEqual(len(gate.selected_applications(self.root, promoted)), 1)
        self.assertEqual(gate.check_component(self.root, self.component)[0], 0)

    def test_exact_path_and_malicious_source(self) -> None:
        self.app["spec"]["syncPolicy"] = {"automated": {}}
        write_yaml(self.apps / "demo.yaml", self.app)
        self.commit("promote")
        promoted = git(self.root, "rev-parse", "HEAD")
        sibling = self.root / "openbank-infra/gitops/components/demo-extra/other.yaml"
        sibling.parent.mkdir(parents=True)
        sibling.write_text("kind: ConfigMap\n")
        self.commit("change similarly named sibling")
        self.assertEqual(gate.selected_applications(self.root, promoted), [])
        for invalid in ("../outside", "/tmp/outside", "openbank-infra/gitops/components/missing"):
            self.app["spec"]["source"]["path"] = invalid
            with self.assertRaises(ValueError):
                gate.source_path(self.root, self.app)
        link = self.root / "openbank-infra/gitops/components/escape"
        link.symlink_to(Path(self.tmp.name).parent, target_is_directory=True)
        self.app["spec"]["source"]["path"] = "openbank-infra/gitops/components/escape"
        with self.assertRaises(ValueError):
            gate.source_path(self.root, self.app)
        internal = self.root / "openbank-infra/gitops/components/internal-link"
        internal.symlink_to(self.comp, target_is_directory=True)
        self.app["spec"]["source"]["path"] = "openbank-infra/gitops/components/internal-link"
        with self.assertRaisesRegex(ValueError, "symlink"):
            gate.source_path(self.root, self.app)

    def test_effective_directory_excludes_staged_workload(self) -> None:
        # Two Applications share one directory; excluded files belong to the other App.
        staged = self.comp / "staged.yaml"
        write_yaml(staged, {"kind": "Deployment", "spec": {"template": {"spec": {"containers": [
            {"image": "example/openbank-unreviewed-service:1"}]}}}})
        self.app["spec"]["source"]["directory"] = {"exclude": "staged.yaml"}
        self.assertEqual(gate.check_component(self.root, self.component, self.app)[0], 0)

    def test_directory_formats_and_unsupported_selected_jsonnet(self) -> None:
        import json

        value = {"kind": "Deployment", "metadata": {"name": "unreviewed"},
                 "spec": {"template": {"spec": {"containers": [
                     {"image": "example/openbank-unreviewed-service:1"}]}}}}
        for suffix in (".yml", ".json"):
            path = self.comp / ("unreviewed" + suffix)
            path.write_text(json.dumps(value) if suffix == ".json" else yaml.safe_dump(value))
            with redirect_stdout(io.StringIO()):
                self.assertGreater(gate.check_component(self.root, self.component, self.app)[0], 0)
            path.unlink()
        (self.comp / "selected.jsonnet").write_text("{kind: 'Deployment'}")
        with self.assertRaisesRegex(ValueError, "Jsonnet"):
            gate.effective_resources(self.root, self.component, self.app)
        self.app["spec"]["source"]["directory"] = {"exclude": "selected.jsonnet"}
        self.assertTrue(gate.effective_resources(self.root, self.component, self.app))

    def test_generator_traversal_symlink_and_nonexecutable_rejected(self) -> None:
        bundle = self.comp / "one-opa-bundle.yaml"
        original = bundle.read_text()
        real = self.comp / "gen-one-opa-bundle.sh"
        link = self.comp / "gen-linked.sh"
        link.symlink_to(real)
        for name in ("gen-../gen-one-opa-bundle.sh", "gen-linked.sh"):
            bundle.write_text(original.replace("gen-one-opa-bundle.sh", name, 1))
            with redirect_stdout(io.StringIO()):
                self.assertGreater(gate.check_component(self.root, self.component)[0], 0)
        bundle.write_text(original)
        real.chmod(0o644)
        with redirect_stdout(io.StringIO()):
            self.assertGreater(gate.check_component(self.root, self.component)[0], 0)

    def test_opa_bundle_must_share_workload_namespace(self) -> None:
        bundle = self.comp / "one-opa-bundle.yaml"
        bundle.write_text(bundle.read_text().replace("namespace: demo", "namespace: other"))
        with redirect_stdout(io.StringIO()):
            self.assertGreater(gate.check_component(self.root, self.component, self.app)[0], 0)

    def test_kustomize_excludes_unlisted_staged_workload(self) -> None:
        (self.comp / "kustomization.yaml").write_text(
            "apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\n"
            "resources:\n  - one.yaml\n  - one-opa-bundle.yaml\n  - postgres.yaml\n  - backup.yaml\n"
        )
        write_yaml(self.comp / "staged.yaml", {"kind": "Deployment", "spec": {"template": {
            "spec": {"containers": [{"image": "example/openbank-unreviewed-service:1"}]}}}})
        self.assertEqual(gate.check_component(self.root, self.component, self.app)[0], 0)

    def test_second_opa_workload_cannot_borrow_first_generator(self) -> None:
        second = dict(self.workload)
        second = yaml.safe_load(yaml.safe_dump(second))
        second["metadata"]["name"] = "two"
        second["spec"]["template"]["spec"]["containers"][0]["image"] = "example/openbank-two-service:1"
        second["spec"]["template"]["spec"]["volumes"][0]["configMap"]["name"] = "two-opa-bundle"
        write_yaml(self.comp / "two.yaml", second)
        self.assertGreater(gate.check_component(self.root, self.component)[0], 0)
        write_yaml(self.comp / "two-opa-bundle.yaml", {"kind": "ConfigMap", "metadata": {
            "name": "two-opa-bundle", "namespace": "demo", "annotations": {gate.CHECKSUM: "abc"}}, "data": {"policy": "fake"}})
        self.assertGreater(gate.check_component(self.root, self.component)[0], 0)
        bundle = self.comp / "two-opa-bundle.yaml"
        bundle.write_text("# GENERATED by gen-one-opa-bundle.sh — do not hand-edit.\n" + bundle.read_text())
        self.commit("forge second bundle provenance")
        findings, bundle_files = gate.check_component(self.root, self.component)
        self.assertEqual(findings, 0)
        self.assertIn("two-opa-bundle.yaml", bundle_files)
        self.assertGreater(gate.verify_generated(self.root, {self.component: bundle_files}), 0)

    def test_second_generator_cannot_validate_forged_first_generator_header(self) -> None:
        second = yaml.safe_load(yaml.safe_dump(self.workload))
        second["metadata"]["name"] = "two"
        second["spec"]["template"]["spec"]["containers"][0]["image"] = "example/openbank-two-service:1"
        second["spec"]["template"]["spec"]["volumes"][0]["configMap"]["name"] = "two-opa-bundle"
        write_yaml(self.comp / "two.yaml", second)
        first = (self.comp / "one-opa-bundle.yaml").read_text()
        (self.comp / "two-opa-bundle.yaml").write_text(first.replace(
            "one-opa-bundle", "two-opa-bundle").replace(
                "gen-two-opa-bundle.sh", "gen-one-opa-bundle.sh", 1))
        generator = self.comp / "gen-two-opa-bundle.sh"
        generator.write_text((self.comp / "gen-one-opa-bundle.sh").read_text().replace(
            "one-opa-bundle", "two-opa-bundle").replace("one.yaml", "two.yaml"))
        generator.chmod(0o755)
        self.commit("two generators with forged second header")
        findings, mapping = gate.check_component(self.root, self.component)
        self.assertEqual(findings, 0)
        self.assertEqual(mapping["two-opa-bundle.yaml"], "gen-one-opa-bundle.sh")
        with redirect_stdout(io.StringIO()):
            self.assertGreater(gate.verify_generated(self.root, {self.component: mapping}), 0)

    def test_nested_bundle_generator_path(self) -> None:
        nested = self.comp / "nested"
        nested.mkdir()
        (self.comp / "one-opa-bundle.yaml").rename(nested / "one-opa-bundle.yaml")
        generator = self.comp / "gen-one-opa-bundle.sh"
        source = generator.read_text().replace(
            "/demo/one-opa-bundle.yaml", "/demo/nested/one-opa-bundle.yaml")
        generator.unlink()
        (nested / generator.name).write_text(source)
        (nested / generator.name).chmod(0o755)
        self.app["spec"]["source"]["directory"] = {"recurse": True}
        self.commit("nested bundle")
        findings, mapping = gate.check_component(self.root, self.component, self.app)
        self.assertEqual(findings, 0)
        self.assertEqual(mapping, {"nested/one-opa-bundle.yaml": "nested/gen-one-opa-bundle.sh"})
        self.assertEqual(gate.verify_generated(self.root, {self.component: mapping}), 0)

    def test_all_standard_pod_controllers_and_init_images_are_checked(self) -> None:
        for kind in ("Deployment", "Rollout", "StatefulSet", "DaemonSet", "Job", "CronJob", "Pod"):
            with self.subTest(kind=kind):
                pod = {"containers": [{"image": "example/plain:1"}],
                       "initContainers": [{"image": "example/openbank-unreviewed-service:1"}]}
                template = {"spec": pod}
                if kind == "Pod":
                    doc = {"kind": kind, "spec": pod}
                elif kind == "CronJob":
                    doc = {"kind": kind, "spec": {"jobTemplate": {"spec": {"template": template}}}}
                else:
                    doc = {"kind": kind, "spec": {"template": template}}
                write_yaml(self.comp / "extra.yaml", doc)
                with redirect_stdout(io.StringIO()):
                    self.assertGreater(gate.check_component(self.root, self.component)[0], 0)
                (self.comp / "extra.yaml").unlink()

    def test_existing_backup_and_model_rules(self) -> None:
        self.assertEqual(gate.check_component(self.root, self.component)[0], 0)
        self.schedule["spec"]["immediate"] = False
        write_yaml(self.comp / "backup.yaml", self.schedule)
        self.assertGreater(gate.check_component(self.root, self.component)[0], 0)
        write_yaml(self.comp / "backup.yaml", {**self.schedule,
                   "spec": {**self.schedule["spec"], "immediate": True}})
        (self.root / "docs/threat-models/openbank-one-service.md").unlink()
        self.assertGreater(gate.check_component(self.root, self.component)[0], 0)

    def test_generator_detects_stale_bundle_and_checksum(self) -> None:
        self.assertEqual(gate.verify_generated(self.root, {self.component: gate.check_component(self.root, self.component)[1]}), 0)
        bundle = self.comp / "one-opa-bundle.yaml"
        bundle.write_text(bundle.read_text().replace("abc", "stale"))
        self.commit("stale generated bundle")
        self.assertGreater(gate.verify_generated(self.root, {self.component: gate.check_component(self.root, self.component)[1]}), 0)
        git(self.root, "reset", "--hard", self.base)
        self.workload["spec"]["template"]["metadata"]["annotations"][gate.CHECKSUM] = "stale"
        write_yaml(self.comp / "one.yaml", self.workload)
        self.commit("stale pod checksum")
        self.assertGreater(gate.verify_generated(self.root, {self.component: gate.check_component(self.root, self.component)[1]}), 0)

    def test_unmapped_platform_db_has_existing_backup_rule(self) -> None:
        (self.comp / "one.yaml").unlink()
        self.assertEqual(gate.check_component(self.root, self.component)[0], 0)
        self.schedule["spec"]["immediate"] = False
        write_yaml(self.comp / "backup.yaml", self.schedule)
        self.assertGreater(gate.check_component(self.root, self.component)[0], 0)


if __name__ == "__main__":
    # Negative controls intentionally emit ::error. Keep those fixture annotations
    # out of successful hosted gate logs; unittest failures still reach stderr.
    with redirect_stdout(io.StringIO()):
        unittest.main()
